def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")
    parts = []
    first = True
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue
        # Determine sign
        if first:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)
        # Determine variable string
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'
        parts.append(f'{sign}{coeff_str}{var_str}')
        first = False
    if not parts:
        return '0'
    return ''.join(parts)

def string_transformation(A: str, B: str, rules: list):
    """
    Perform string transformation from A to B using a set of transformation rules.
    Applies BFS up to 10 steps and returns the minimum number of steps required.
    If impossible within 10 steps, returns "NO ANSWER!".
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str):
        return "NO ANSWER!"
    if not isinstance(rules, list):
        return "NO ANSWER!"
    # Validate each rule is a tuple of two strings
    for r in rules:
        if (
            not isinstance(r, tuple)
            or len(r) != 2
            or not isinstance(r[0], str)
            or not isinstance(r[1], str)
        ):
            return "NO ANSWER!"

    # BFS initialization
    visited = {A}
    queue = [(A, 0)]
    max_steps = 10

    while queue:
        current, steps = queue.pop(0)
        if current == B:
            return steps
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                pos = current.find(src, start)
                if pos == -1:
                    break
                new_str = current[:pos] + tgt + current[pos + len(src) :]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = pos + 1  # allow overlapping matches

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Parameters:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if not isinstance(num, int):
        raise TypeError("num must be an integer")
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    max_factor = int(num**0.5) + 1
    while i <= max_factor:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

